patch:
diff --git a/tools/repro-emfile-fix.js b/tools/repro-emfile-fix.js
new file mode 100644
index 0000000..b61b461
--- /dev/null
+++ b/tools/repro-emfile-fix.js
@@ -0,0 +1,67 @@
+/**
+ * @fileoverview Reproduction for eslint/eslint#19924: `--fix` throws EMFILE
+ * from ESLint.outputFixes when many files have fixes to write.
+ *
+ * Usage: node tools/repro-emfile-fix.js [fileCount] [openFileLimit]
+ * Exit code 1 = bug reproduced, 0 = not reproduced.
+ */
+
+"use strict";
+
+const fs = require("node:fs");
+const path = require("node:path");
+const { spawnSync } = require("node:child_process");
+
+const FILE_COUNT = Number(process.argv[2]) || 5000;
+const FD_LIMIT = Number(process.argv[3]) || 1024;
+const OUTPUT_DIRECTORY = "tmp/emfile-fix-repro";
+const ESLINT_BIN = path.resolve(__dirname, "../bin/eslint.js");
+
+function generateFiles() {
+	fs.rmSync(OUTPUT_DIRECTORY, { recursive: true, force: true, maxRetries: 8 });
+	fs.mkdirSync(OUTPUT_DIRECTORY, { recursive: true });
+
+	// no trailing newline, so `eol-last` produces a fix for every file
+	for (let i = 0; i < FILE_COUNT; i++) {
+		fs.writeFileSync(`${OUTPUT_DIRECTORY}/file_${i}.js`, `// This is file ${i}`);
+	}
+}
+
+function runESLint(extraArgs) {
+	const cmd = [
+		`ulimit -n ${FD_LIMIT}`,
+		`exec "${process.execPath}" "${ESLINT_BIN}" ${OUTPUT_DIRECTORY} --no-config-lookup --rule "eol-last: [error, always]" ${extraArgs}`,
+	].join(" && ");
+
+	return spawnSync("bash", ["-c", cmd], { encoding: "utf8", maxBuffer: 1 << 30 });
+}
+
+function countFixed() {
+	return fs
+		.readdirSync(OUTPUT_DIRECTORY)
+		.filter(f => fs.readFileSync(`${OUTPUT_DIRECTORY}/${f}`, "utf8").endsWith("\n")).length;
+}
+
+console.log(`Node ${process.version}, ${FILE_COUNT} files, open-file limit ${FD_LIMIT}`);
+generateFiles();
+
+// Control: linting alone (reads go through @humanwhocodes/retry) must not hit EMFILE.
+const lint = runESLint("--format json");
+const lintResults = JSON.parse(lint.stdout);
+const fixable = lintResults.filter(r => r.fixableErrorCount > 0).length;
+console.log(`[control] lint without --fix: exit ${lint.status}, ${lintResults.length} files linted, ${fixable} fixable, EMFILE in stderr: ${/EMFILE/u.test(lint.stderr)}`);
+
+// Bug: same run with --fix; outputFixes calls fs.writeFile for every file at once.
+const fix = runESLint("--fix");
+const emfile = /EMFILE/u.test(fix.stderr);
+console.log(`[--fix] exit ${fix.status}, files fixed on disk: ${countFixed()}/${FILE_COUNT}`);
+console.log("[--fix] stderr:\n" + fix.stderr.split("\n").slice(0, 12).join("\n"));
+
+fs.rmSync(OUTPUT_DIRECTORY, { recursive: true, force: true, maxRetries: 8 });
+
+if (emfile && /outputFixes/u.test(fix.stderr)) {
+	console.log("BUG REPRODUCED: EMFILE thrown from ESLint.outputFixes during --fix");
+	process.exitCode = 1;
+} else {
+	console.log("Bug not reproduced");
+}
